1	*{box-sizing:border-box}html,body{margin:0;height:100%;background:#17202a;color:#f4f6f7;font:16px system-ui}button{font:inherit;color:inherit;background:#263544;border:1px solid #536777;border-radius:5px;padding:6px 12px;margin:3px;min-height:36px}button:focus-visible{outline:3px solid #7ed7ff;outline-offset:1px}button:disabled{opacity:.55}.bar .surface-bar{display:flex;height:48px;overflow-x:auto;overflow-y:hidden;align-items:center;flex-wrap:nowrap}.control-label{display:block;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.control-detail{display:block;font-size:13px;line-height:13px;white-space:normal;overflow-wrap:anywhere}.control-detail:empty{display:none}.bar .surface-bar>button{margin:1px;padding:0 4px;min-height:46px;max-height:46px;min-width:0;max-width:240px;line-height:18px;flex:0 0 80px}.bar .surface-bar>.control-group{flex:1 1 116px;min-width:112px}.bar .surface-bar>.control-recovery{flex:0 0 120px}.bar .control-recovery .control-label{font-size:14px;white-space:normal;line-height:15px;overflow:visible}.bar [role=status]{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.popup .surface-popup{height:100vh;overflow:auto;padding:8px}.popup .surface-popup>h1{font-size:20px;line-height:24px;margin:0 0 4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.popup .surface-popup>p[role=status]{line-height:20px;margin:0 0 8px;white-space:normal;overflow-wrap:anywhere}.popup button{display:block;width:calc(100% - 6px);text-align:left}.popup .control-detail{margin-top:4px;font-size:14px;line-height:18px}.popup [role=status]{margin:6px}
