1	'use strict';
2	const app = Elm.Popup.init({node:document.getElementById('app')});
3	window.submitSurfaceAction = value => app.ports.requestAction.send(value);
4	const post = value => window.webkit.messageHandlers.native.postMessage(JSON.stringify(value));
5	window.receivePresentation = value => {
6	  app.ports.presentation.send(value);
7	  requestAnimationFrame(() => requestAnimationFrame(() => {
8	    const node=document.querySelector('.surface-popup');
9	    if (node?.dataset.publication===value.publication && node.dataset.lease===value.lease) {
10	      post({surfaceProtocol:2,kind:'presentation-applied',publication:value.publication,lease:value.lease});
11	    }
12	  }));
13	};
14	window.receiveFocus = value => requestAnimationFrame(() => {
15	  const node=document.querySelector('.surface-popup');
16	  if(value.surfaceProtocol!==2 || value.kind!=='surface-focus' || !node || node.dataset.publication!==value.publication || node.dataset.lease!==value.lease) return;
17	  const focused=[];
18	  for (const target of value.targets) {
19	    const control=document.getElementById(target);
20	    if(control && node.contains(control) && !control.disabled){control.focus();if(document.activeElement===control) focused.push(target);}
21	  }
22	  post({surfaceProtocol:2,kind:'focus-applied',publication:value.publication,lease:value.lease,targets:focused});
23	});
24	app.ports.actions.subscribe(post);
25	post({surfaceProtocol:2,kind:'presentation-ready'});
26	
27	if (window.elmHostQA) {
28	  let last='';
